import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadTravancoreData(){const e=readFileSync(resolve(__dirname,"../../travancore-kingdom-explorer/travancore-data.js"),"utf-8");return new Function(e+"\nreturn { TRAVANCORE_INFO, TIMELINE_DATA, RULERS_DATA, CONTRIBUTIONS_DATA, GALLERY_IMAGES, REFERENCES };")()}describe("Kingdom of Travancore Explorer — Data Tests",()=>{let e;beforeAll(()=>{e=loadTravancoreData()}),describe("TRAVANCORE_INFO metadata",()=>{it("contains correct Kingdom of Travancore attributes",()=>{expect(e.TRAVANCORE_INFO.id).toBe("travancore-kingdom"),expect(e.TRAVANCORE_INFO.name).toBe("Kingdom of Travancore"),expect(e.TRAVANCORE_INFO.period).toContain("1729"),expect(e.TRAVANCORE_INFO.deity).toContain("Lord Padmanabha")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.TRAVANCORE_INFO.quickStats)).toBe(!0),expect(e.TRAVANCORE_INFO.quickStats.length).toBe(6)})}),describe("TIMELINE_DATA & RULERS_DATA",()=>{it("contains milestone timeline items and key rulers",()=>{expect(Array.isArray(e.TIMELINE_DATA)).toBe(!0),expect(e.TIMELINE_DATA.length).toBeGreaterThanOrEqual(5),expect(Array.isArray(e.RULERS_DATA)).toBe(!0),expect(e.RULERS_DATA.length).toBeGreaterThanOrEqual(4)})}),describe("CONTRIBUTIONS_DATA",()=>{it("contains required contribution fields",()=>{expect(e.CONTRIBUTIONS_DATA.overview).toBeDefined(),expect(e.CONTRIBUTIONS_DATA.militaryNaval).toBeDefined(),expect(e.CONTRIBUTIONS_DATA.architecture).toBeDefined(),expect(e.CONTRIBUTIONS_DATA.educationSocial).toBeDefined(),expect(e.CONTRIBUTIONS_DATA.musicCulture).toBeDefined()})}),describe("GALLERY_IMAGES & REFERENCES",()=>{it("has non-empty gallery and references",()=>{expect(Array.isArray(e.GALLERY_IMAGES)).toBe(!0),expect(e.GALLERY_IMAGES.length).toBeGreaterThanOrEqual(2),expect(Array.isArray(e.REFERENCES)).toBe(!0),expect(e.REFERENCES.length).toBeGreaterThanOrEqual(2)})})});